    # the diagonal sweep moving downward through the grid.
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not seeds:
        return out

    reached = set(seeds)
    stack = list(seeds)
    while stack:
        r, c = stack.pop()
        for nr, nc in ((r + 1, c - 1), (r + 1, c), (r + 1, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in reached:
                if grid[nr][nc] == bg:
                    reached.add((nr, nc))
                    stack.append((nr, nc))
    for r, c in reached:
        if grid[r][c] == bg:
